    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The bar chart below shows the percentage of households with access to the internet in three countries in 2005, 2012 and 2019.</p><svg viewBox="0 0 560 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="18" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">Households with internet access (%)</text><line x1="60" y1="260" x2="530" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="54" y="264" text-anchor="end" font-size="11" fill="#8A7F6E">0</text><line x1="60" y1="216" x2="530" y2="216" stroke="#eadfce" stroke-width="1"/><text x="54" y="220" text-anchor="end" font-size="11" fill="#8A7F6E">20</text><line x1="60" y1="172" x2="530" y2="172" stroke="#eadfce" stroke-width="1"/><text x="54" y="176" text-anchor="end" font-size="11" fill="#8A7F6E">40</text><line x1="60" y1="128" x2="530" y2="128" stroke="#eadfce" stroke-width="1"/><text x="54" y="132" text-anchor="end" font-size="11" fill="#8A7F6E">60</text><line x1="60" y1="84" x2="530" y2="84" stroke="#eadfce" stroke-width="1"/><text x="54" y="88" text-anchor="end" font-size="11" fill="#8A7F6E">80</text><line x1="60" y1="40" x2="530" y2="40" stroke="#eadfce" stroke-width="1"/><text x="54" y="44" text-anchor="end" font-size="11" fill="#8A7F6E">100</text><line x1="60" y1="40" x2="60" y2="260" stroke="#8A7F6E" stroke-width="1"/><rect x="89.8" y="154.4" width="32.4" height="105.6" fill="#2E6E6A"/><text x="106.0" y="150.4" text-anchor="middle" font-size="10" fill="#8A7F6E">48</text><rect x="122.1" y="222.6" width="32.4" height="37.4" fill="#B78A2E"/><text x="138.3" y="218.6" text-anchor="middle" font-size="10" fill="#8A7F6E">17</text><rect x="154.5" y="233.6" width="32.4" height="26.4" fill="#6E4A8E"/><text x="170.7" y="229.6" text-anchor="middle" font-size="10" fill="#8A7F6E">12</text><text x="138.3" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2005</text><rect x="246.4" y="101.6" width="32.4" height="158.4" fill="#2E6E6A"/><text x="262.6" y="97.6" text-anchor="middle" font-size="10" fill="#8A7F6E">72</text><rect x="278.8" y="161.0" width="32.4" height="99.0" fill="#B78A2E"/><text x="295.0" y="157.0" text-anchor="middle" font-size="10" fill="#8A7F6E">45</text><rect x="311.2" y="185.2" width="32.4" height="74.8" fill="#6E4A8E"/><text x="327.4" y="181.2" text-anchor="middle" font-size="10" fill="#8A7F6E">34</text><text x="295.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2012</text><rect x="403.1" y="59.8" width="32.4" height="200.2" fill="#2E6E6A"/><text x="419.3" y="55.8" text-anchor="middle" font-size="10" fill="#8A7F6E">91</text><rect x="435.5" y="97.2" width="32.4" height="162.8" fill="#B78A2E"/><text x="451.7" y="93.2" text-anchor="middle" font-size="10" fill="#8A7F6E">74</text><rect x="467.9" y="132.4" width="32.4" height="127.6" fill="#6E4A8E"/><text x="484.0" y="128.4" text-anchor="middle" font-size="10" fill="#8A7F6E">58</text><text x="451.7" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2019</text><rect x="90" y="300" width="12" height="12" fill="#2E6E6A"/><text x="106" y="310" font-size="11" fill="#8A7F6E">Japan</text><rect x="170" y="300" width="12" height="12" fill="#B78A2E"/><text x="186" y="310" font-size="11" fill="#8A7F6E">Brazil</text><rect x="258" y="300" width="12" height="12" fill="#6E4A8E"/><text x="274" y="310" font-size="11" fill="#8A7F6E">Egypt</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Some people think that governments should spend money on public services rather than on the arts, such as music and theatre. To what extent do you agree or disagree?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-2','Gri Writing 2',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
