    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The line graph below shows the average monthly temperature in three cities over the course of a year.</p><svg viewBox="0 0 560 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="18" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">Average monthly temperature (°C)</text><line x1="60" y1="260" x2="530" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="54" y="264" text-anchor="end" font-size="11" fill="#8A7F6E">0</text><line x1="60" y1="216" x2="530" y2="216" stroke="#eadfce" stroke-width="1"/><text x="54" y="220" text-anchor="end" font-size="11" fill="#8A7F6E">7</text><line x1="60" y1="172" x2="530" y2="172" stroke="#eadfce" stroke-width="1"/><text x="54" y="176" text-anchor="end" font-size="11" fill="#8A7F6E">14</text><line x1="60" y1="128" x2="530" y2="128" stroke="#eadfce" stroke-width="1"/><text x="54" y="132" text-anchor="end" font-size="11" fill="#8A7F6E">21</text><line x1="60" y1="84" x2="530" y2="84" stroke="#eadfce" stroke-width="1"/><text x="54" y="88" text-anchor="end" font-size="11" fill="#8A7F6E">28</text><line x1="60" y1="40" x2="530" y2="40" stroke="#eadfce" stroke-width="1"/><text x="54" y="44" text-anchor="end" font-size="11" fill="#8A7F6E">35</text><line x1="60" y1="40" x2="60" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="60.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Jan</text><text x="154.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Mar</text><text x="248.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">May</text><text x="342.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Jul</text><text x="436.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Sep</text><text x="530.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Nov</text><polyline points="60.0,140.6 154.0,109.1 248.0,52.6 342.0,40.0 436.0,58.9 530.0,109.1 " fill="none" stroke="#B78A2E" stroke-width="2.5"/><circle cx="60.0" cy="140.6" r="3" fill="#B78A2E"/><circle cx="154.0" cy="109.1" r="3" fill="#B78A2E"/><circle cx="248.0" cy="52.6" r="3" fill="#B78A2E"/><circle cx="342.0" cy="40.0" r="3" fill="#B78A2E"/><circle cx="436.0" cy="58.9" r="3" fill="#B78A2E"/><circle cx="530.0" cy="109.1" r="3" fill="#B78A2E"/><polyline points="60.0,209.7 154.0,184.6 248.0,134.3 342.0,84.0 436.0,109.1 530.0,178.3 " fill="none" stroke="#2E6E6A" stroke-width="2.5"/><circle cx="60.0" cy="209.7" r="3" fill="#2E6E6A"/><circle cx="154.0" cy="184.6" r="3" fill="#2E6E6A"/><circle cx="248.0" cy="134.3" r="3" fill="#2E6E6A"/><circle cx="342.0" cy="84.0" r="3" fill="#2E6E6A"/><circle cx="436.0" cy="109.1" r="3" fill="#2E6E6A"/><circle cx="530.0" cy="178.3" r="3" fill="#2E6E6A"/><polyline points="60.0,285.1 154.0,253.7 248.0,190.9 342.0,146.9 436.0,184.6 530.0,247.4 " fill="none" stroke="#6E4A8E" stroke-width="2.5"/><circle cx="60.0" cy="285.1" r="3" fill="#6E4A8E"/><circle cx="154.0" cy="253.7" r="3" fill="#6E4A8E"/><circle cx="248.0" cy="190.9" r="3" fill="#6E4A8E"/><circle cx="342.0" cy="146.9" r="3" fill="#6E4A8E"/><circle cx="436.0" cy="184.6" r="3" fill="#6E4A8E"/><circle cx="530.0" cy="247.4" r="3" fill="#6E4A8E"/><rect x="90" y="300" width="12" height="12" fill="#B78A2E"/><text x="106" y="310" font-size="11" fill="#8A7F6E">Dubai</text><rect x="170" y="300" width="12" height="12" fill="#2E6E6A"/><text x="186" y="310" font-size="11" fill="#8A7F6E">Rome</text><rect x="242" y="300" width="12" height="12" fill="#6E4A8E"/><text x="258" y="310" font-size="11" fill="#8A7F6E">Oslo</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Many people believe that social media has a negative effect on society. Discuss both this view and the opposite view, and give your own opinion.</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-3','Gri Writing 3',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The table below gives information about the number of hours per week that people in different age groups spent on four leisure activities in one country.</p><table style="width:100%;border-collapse:collapse;font-size:14px;margin-top:6px"><caption style="caption-side:top;text-align:left;color:#8A7F6E;font-weight:bold;padding-bottom:6px">Weekly hours spent on leisure activities, by age group</caption><thead><tr><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:left">Activity</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">16–24</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">25–44</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">45–64</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">65+</th></tr></thead><tbody><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">Watching TV</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">9</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">14</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">18</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">26</td></tr><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">Social media</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">13</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">8</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">4</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">2</td></tr><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">Reading</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">3</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">5</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">7</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">11</td></tr><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">Exercise</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">6</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">5</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">4</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">3</td></tr></tbody></table><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>In many countries, the amount of crime committed by teenagers is rising. What are the causes of this, and what solutions can you suggest?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-4','Gri Writing 4',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The bar chart below compares the amount of energy (in millions of units) used by four sectors of an economy in 1990 and 2020.</p><svg viewBox="0 0 560 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="18" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">Energy use by sector (million units)</text><line x1="60" y1="260" x2="530" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="54" y="264" text-anchor="end" font-size="11" fill="#8A7F6E">0</text><line x1="60" y1="216" x2="530" y2="216" stroke="#eadfce" stroke-width="1"/><text x="54" y="220" text-anchor="end" font-size="11" fill="#8A7F6E">24</text><line x1="60" y1="172" x2="530" y2="172" stroke="#eadfce" stroke-width="1"/><text x="54" y="176" text-anchor="end" font-size="11" fill="#8A7F6E">48</text><line x1="60" y1="128" x2="530" y2="128" stroke="#eadfce" stroke-width="1"/><text x="54" y="132" text-anchor="end" font-size="11" fill="#8A7F6E">72</text><line x1="60" y1="84" x2="530" y2="84" stroke="#eadfce" stroke-width="1"/><text x="54" y="88" text-anchor="end" font-size="11" fill="#8A7F6E">96</text><line x1="60" y1="40" x2="530" y2="40" stroke="#eadfce" stroke-width="1"/><text x="54" y="44" text-anchor="end" font-size="11" fill="#8A7F6E">120</text><line x1="60" y1="40" x2="60" y2="260" stroke="#8A7F6E" stroke-width="1"/><rect x="82.3" y="85.8" width="36.4" height="174.2" fill="#2E6E6A"/><text x="100.5" y="81.8" text-anchor="middle" font-size="10" fill="#8A7F6E">95</text><rect x="118.8" y="124.3" width="36.4" height="135.7" fill="#B78A2E"/><text x="137.0" y="120.3" text-anchor="middle" font-size="10" fill="#8A7F6E">74</text><text x="118.8" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Industry</text><rect x="199.8" y="150.0" width="36.4" height="110.0" fill="#2E6E6A"/><text x="218.0" y="146.0" text-anchor="middle" font-size="10" fill="#8A7F6E">60</text><rect x="236.2" y="62.0" width="36.4" height="198.0" fill="#B78A2E"/><text x="254.5" y="58.0" text-anchor="middle" font-size="10" fill="#8A7F6E">108</text><text x="236.2" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Transport</text><rect x="317.3" y="128.0" width="36.4" height="132.0" fill="#2E6E6A"/><text x="335.5" y="124.0" text-anchor="middle" font-size="10" fill="#8A7F6E">72</text><rect x="353.8" y="98.7" width="36.4" height="161.3" fill="#B78A2E"/><text x="372.0" y="94.7" text-anchor="middle" font-size="10" fill="#8A7F6E">88</text><text x="353.8" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Homes</text><rect x="434.8" y="208.7" width="36.4" height="51.3" fill="#2E6E6A"/><text x="453.0" y="204.7" text-anchor="middle" font-size="10" fill="#8A7F6E">28</text><rect x="471.2" y="139.0" width="36.4" height="121.0" fill="#B78A2E"/><text x="489.5" y="135.0" text-anchor="middle" font-size="10" fill="#8A7F6E">66</text><text x="471.2" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Services</text><rect x="90" y="300" width="12" height="12" fill="#2E6E6A"/><text x="106" y="310" font-size="11" fill="#8A7F6E">1990</text><rect x="162" y="300" width="12" height="12" fill="#B78A2E"/><text x="178" y="310" font-size="11" fill="#8A7F6E">2020</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Some people believe that unpaid work, such as caring for family members, should be recognised as employment by the government. To what extent do you agree or disagree?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-5','Gri Writing 5',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The line graph below shows the population of three cities from 1980 to 2020.</p><svg viewBox="0 0 560 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="18" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">City population (millions)</text><line x1="60" y1="260" x2="530" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="54" y="264" text-anchor="end" font-size="11" fill="#8A7F6E">0</text><line x1="60" y1="216" x2="530" y2="216" stroke="#eadfce" stroke-width="1"/><text x="54" y="220" text-anchor="end" font-size="11" fill="#8A7F6E">2.4</text><line x1="60" y1="172" x2="530" y2="172" stroke="#eadfce" stroke-width="1"/><text x="54" y="176" text-anchor="end" font-size="11" fill="#8A7F6E">4.8</text><line x1="60" y1="128" x2="530" y2="128" stroke="#eadfce" stroke-width="1"/><text x="54" y="132" text-anchor="end" font-size="11" fill="#8A7F6E">7.2</text><line x1="60" y1="84" x2="530" y2="84" stroke="#eadfce" stroke-width="1"/><text x="54" y="88" text-anchor="end" font-size="11" fill="#8A7F6E">9.6</text><line x1="60" y1="40" x2="530" y2="40" stroke="#eadfce" stroke-width="1"/><text x="54" y="44" text-anchor="end" font-size="11" fill="#8A7F6E">12</text><line x1="60" y1="40" x2="60" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="60.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">1980</text><text x="177.5" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">1990</text><text x="295.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2000</text><text x="412.5" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2010</text><text x="530.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2020</text><polyline points="60.0,212.3 177.5,172.0 295.0,128.0 412.5,87.7 530.0,49.2 " fill="none" stroke="#B78A2E" stroke-width="2.5"/><circle cx="60.0" cy="212.3" r="3" fill="#B78A2E"/><circle cx="177.5" cy="172.0" r="3" fill="#B78A2E"/><circle cx="295.0" cy="128.0" r="3" fill="#B78A2E"/><circle cx="412.5" cy="87.7" r="3" fill="#B78A2E"/><circle cx="530.0" cy="49.2" r="3" fill="#B78A2E"/><polyline points="60.0,161.0 177.5,133.5 295.0,111.5 412.5,91.3 530.0,74.8 " fill="none" stroke="#2E6E6A" stroke-width="2.5"/><circle cx="60.0" cy="161.0" r="3" fill="#2E6E6A"/><circle cx="177.5" cy="133.5" r="3" fill="#2E6E6A"/><circle cx="295.0" cy="111.5" r="3" fill="#2E6E6A"/><circle cx="412.5" cy="91.3" r="3" fill="#2E6E6A"/><circle cx="530.0" cy="74.8" r="3" fill="#2E6E6A"/><polyline points="60.0,203.2 177.5,199.5 295.0,197.7 412.5,195.8 530.0,197.7 " fill="none" stroke="#6E4A8E" stroke-width="2.5"/><circle cx="60.0" cy="203.2" r="3" fill="#6E4A8E"/><circle cx="177.5" cy="199.5" r="3" fill="#6E4A8E"/><circle cx="295.0" cy="197.7" r="3" fill="#6E4A8E"/><circle cx="412.5" cy="195.8" r="3" fill="#6E4A8E"/><circle cx="530.0" cy="197.7" r="3" fill="#6E4A8E"/><rect x="90" y="300" width="12" height="12" fill="#B78A2E"/><text x="106" y="310" font-size="11" fill="#8A7F6E">Lagos</text><rect x="170" y="300" width="12" height="12" fill="#2E6E6A"/><text x="186" y="310" font-size="11" fill="#8A7F6E">Cairo</text><rect x="250" y="300" width="12" height="12" fill="#6E4A8E"/><text x="266" y="310" font-size="11" fill="#8A7F6E">Athens</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Nowadays many people choose to live in large cities. What are the advantages and disadvantages of urban living?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-6','Gri Writing 6',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The table below shows the number of international students (in thousands) enrolled in four countries in three separate years.</p><table style="width:100%;border-collapse:collapse;font-size:14px;margin-top:6px"><caption style="caption-side:top;text-align:left;color:#8A7F6E;font-weight:bold;padding-bottom:6px">International student enrolment (thousands)</caption><thead><tr><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:left">Country</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">2000</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">2010</th><th style="border:1px solid #E3D8C3;padding:6px 9px;background:#F4F2EC;text-align:center">2020</th></tr></thead><tbody><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">United States</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">475</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">690</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">915</td></tr><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">United Kingdom</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">225</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">405</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">485</td></tr><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">Australia</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">120</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">270</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">420</td></tr><tr><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:left;font-weight:600">Canada</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">40</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">95</td><td style="border:1px solid #E3D8C3;padding:6px 9px;text-align:center">325</td></tr></tbody></table><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Some people think that children should start school at a very early age, while others believe they should not begin formal education until they are older. Discuss both views and give your own opinion.</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-7','Gri Writing 7',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The bar chart below shows the number of visitors (in thousands) to five tourist attractions in a European city in one year.</p><svg viewBox="0 0 560 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="18" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">Annual visitors (thousands)</text><line x1="60" y1="260" x2="530" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="54" y="264" text-anchor="end" font-size="11" fill="#8A7F6E">0</text><line x1="60" y1="216" x2="530" y2="216" stroke="#eadfce" stroke-width="1"/><text x="54" y="220" text-anchor="end" font-size="11" fill="#8A7F6E">180</text><line x1="60" y1="172" x2="530" y2="172" stroke="#eadfce" stroke-width="1"/><text x="54" y="176" text-anchor="end" font-size="11" fill="#8A7F6E">360</text><line x1="60" y1="128" x2="530" y2="128" stroke="#eadfce" stroke-width="1"/><text x="54" y="132" text-anchor="end" font-size="11" fill="#8A7F6E">540</text><line x1="60" y1="84" x2="530" y2="84" stroke="#eadfce" stroke-width="1"/><text x="54" y="88" text-anchor="end" font-size="11" fill="#8A7F6E">720</text><line x1="60" y1="40" x2="530" y2="40" stroke="#eadfce" stroke-width="1"/><text x="54" y="44" text-anchor="end" font-size="11" fill="#8A7F6E">900</text><line x1="60" y1="40" x2="60" y2="260" stroke="#8A7F6E" stroke-width="1"/><rect x="77.9" y="59.6" width="58.3" height="200.4" fill="#2E6E6A"/><text x="107.0" y="55.6" text-anchor="middle" font-size="10" fill="#8A7F6E">820</text><text x="107.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Castle</text><rect x="171.9" y="103.6" width="58.3" height="156.4" fill="#2E6E6A"/><text x="201.0" y="99.6" text-anchor="middle" font-size="10" fill="#8A7F6E">640</text><text x="201.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Museum</text><rect x="265.9" y="128.0" width="58.3" height="132.0" fill="#2E6E6A"/><text x="295.0" y="124.0" text-anchor="middle" font-size="10" fill="#8A7F6E">540</text><text x="295.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Cathedral</text><rect x="359.9" y="74.2" width="58.3" height="185.8" fill="#2E6E6A"/><text x="389.0" y="70.2" text-anchor="middle" font-size="10" fill="#8A7F6E">760</text><text x="389.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Park</text><rect x="453.9" y="184.2" width="58.3" height="75.8" fill="#2E6E6A"/><text x="483.0" y="180.2" text-anchor="middle" font-size="10" fill="#8A7F6E">310</text><text x="483.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">Gallery</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>International tourism has brought enormous benefits to many places. At the same time, there is concern about its impact on local residents and the environment. Do the advantages of tourism outweigh the disadvantages?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-8','Gri Writing 8',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
