    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The diagram below shows the process by which glass bottles are recycled and reused.</p><svg viewBox="0 0 560 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="20" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">The glass bottle recycling process</text><rect x="30" y="44" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#2E6E6A" stroke-width="2"/><text x="105" y="66" text-anchor="middle" font-size="11" fill="#8A7F6E">Used bottles</text><text x="105" y="80" text-anchor="middle" font-size="11" fill="#8A7F6E">collected from homes</text><text x="105" y="94" text-anchor="middle" font-size="11" fill="#8A7F6E">and bins</text><circle cx="44" cy="58" r="10" fill="#2E6E6A"/><text x="44" y="62" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">1</text><line x1="182" y1="76" x2="202" y2="76" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="202,72 208,76 202,80" fill="#8A7F6E"/><rect x="204" y="44" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#B78A2E" stroke-width="2"/><text x="279" y="66" text-anchor="middle" font-size="11" fill="#8A7F6E">Bottles transported</text><text x="279" y="80" text-anchor="middle" font-size="11" fill="#8A7F6E">to the recycling</text><text x="279" y="94" text-anchor="middle" font-size="11" fill="#8A7F6E">plant</text><circle cx="218" cy="58" r="10" fill="#B78A2E"/><text x="218" y="62" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">2</text><line x1="356" y1="76" x2="376" y2="76" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="376,72 382,76 376,80" fill="#8A7F6E"/><rect x="378" y="44" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#6E4A8E" stroke-width="2"/><text x="453" y="73" text-anchor="middle" font-size="11" fill="#8A7F6E">Glass washed and</text><text x="453" y="87" text-anchor="middle" font-size="11" fill="#8A7F6E">sorted by colour</text><circle cx="392" cy="58" r="10" fill="#6E4A8E"/><text x="392" y="62" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">3</text><line x1="453" y1="110" x2="453" y2="156" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="449,156 453,162 457,156" fill="#8A7F6E"/><rect x="378" y="162" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#2E6E6A" stroke-width="2"/><text x="453" y="191" text-anchor="middle" font-size="11" fill="#8A7F6E">Crushed into small</text><text x="453" y="205" text-anchor="middle" font-size="11" fill="#8A7F6E">pieces called cullet</text><circle cx="392" cy="176" r="10" fill="#2E6E6A"/><text x="392" y="180" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">4</text><line x1="376" y1="194" x2="358" y2="194" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="358,190 352,194 358,198" fill="#8A7F6E"/><rect x="204" y="162" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#B78A2E" stroke-width="2"/><text x="279" y="191" text-anchor="middle" font-size="11" fill="#8A7F6E">Cullet melted in a</text><text x="279" y="205" text-anchor="middle" font-size="11" fill="#8A7F6E">furnace at high heat</text><circle cx="218" cy="176" r="10" fill="#B78A2E"/><text x="218" y="180" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">5</text><line x1="202" y1="194" x2="184" y2="194" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="184,190 178,194 184,198" fill="#8A7F6E"/><rect x="30" y="162" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#6E4A8E" stroke-width="2"/><text x="105" y="191" text-anchor="middle" font-size="11" fill="#8A7F6E">Molten glass moulded</text><text x="105" y="205" text-anchor="middle" font-size="11" fill="#8A7F6E">into new bottles</text><circle cx="44" cy="176" r="10" fill="#6E4A8E"/><text x="44" y="180" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">6</text><line x1="105" y1="228" x2="105" y2="274" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="101,274 105,280 109,274" fill="#8A7F6E"/><rect x="30" y="280" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#2E6E6A" stroke-width="2"/><text x="105" y="309" text-anchor="middle" font-size="11" fill="#8A7F6E">New bottles filled</text><text x="105" y="323" text-anchor="middle" font-size="11" fill="#8A7F6E">and sent to shops</text><circle cx="44" cy="294" r="10" fill="#2E6E6A"/><text x="44" y="298" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">7</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Many everyday products are designed to be thrown away after a short time. Some people believe manufacturers should make products that last longer. To what extent do you agree or disagree?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-9','Gri Writing 9',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The bar chart below shows the percentage of people in one country who used three methods of communication for personal contact in 2000, 2010 and 2020.</p><svg viewBox="0 0 560 330" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="18" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">Use of communication methods (%)</text><line x1="60" y1="260" x2="530" y2="260" stroke="#8A7F6E" stroke-width="1"/><text x="54" y="264" text-anchor="end" font-size="11" fill="#8A7F6E">0</text><line x1="60" y1="216" x2="530" y2="216" stroke="#eadfce" stroke-width="1"/><text x="54" y="220" text-anchor="end" font-size="11" fill="#8A7F6E">20</text><line x1="60" y1="172" x2="530" y2="172" stroke="#eadfce" stroke-width="1"/><text x="54" y="176" text-anchor="end" font-size="11" fill="#8A7F6E">40</text><line x1="60" y1="128" x2="530" y2="128" stroke="#eadfce" stroke-width="1"/><text x="54" y="132" text-anchor="end" font-size="11" fill="#8A7F6E">60</text><line x1="60" y1="84" x2="530" y2="84" stroke="#eadfce" stroke-width="1"/><text x="54" y="88" text-anchor="end" font-size="11" fill="#8A7F6E">80</text><line x1="60" y1="40" x2="530" y2="40" stroke="#eadfce" stroke-width="1"/><text x="54" y="44" text-anchor="end" font-size="11" fill="#8A7F6E">100</text><line x1="60" y1="40" x2="60" y2="260" stroke="#8A7F6E" stroke-width="1"/><rect x="89.8" y="79.6" width="32.4" height="180.4" fill="#2E6E6A"/><text x="106.0" y="75.6" text-anchor="middle" font-size="10" fill="#8A7F6E">82</text><rect x="122.1" y="207.2" width="32.4" height="52.8" fill="#B78A2E"/><text x="138.3" y="203.2" text-anchor="middle" font-size="10" fill="#8A7F6E">24</text><rect x="154.5" y="255.6" width="32.4" height="4.4" fill="#6E4A8E"/><text x="170.7" y="251.6" text-anchor="middle" font-size="10" fill="#8A7F6E">2</text><text x="138.3" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2000</text><rect x="246.4" y="141.2" width="32.4" height="118.8" fill="#2E6E6A"/><text x="262.6" y="137.2" text-anchor="middle" font-size="10" fill="#8A7F6E">54</text><rect x="278.8" y="110.4" width="32.4" height="149.6" fill="#B78A2E"/><text x="295.0" y="106.4" text-anchor="middle" font-size="10" fill="#8A7F6E">68</text><rect x="311.2" y="191.8" width="32.4" height="68.2" fill="#6E4A8E"/><text x="327.4" y="187.8" text-anchor="middle" font-size="10" fill="#8A7F6E">31</text><text x="295.0" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2010</text><rect x="403.1" y="213.8" width="32.4" height="46.2" fill="#2E6E6A"/><text x="419.3" y="209.8" text-anchor="middle" font-size="10" fill="#8A7F6E">21</text><rect x="435.5" y="86.2" width="32.4" height="173.8" fill="#B78A2E"/><text x="451.7" y="82.2" text-anchor="middle" font-size="10" fill="#8A7F6E">79</text><rect x="467.9" y="66.4" width="32.4" height="193.6" fill="#6E4A8E"/><text x="484.0" y="62.4" text-anchor="middle" font-size="10" fill="#8A7F6E">88</text><text x="451.7" y="278" text-anchor="middle" font-size="11" fill="#8A7F6E">2020</text><rect x="90" y="300" width="12" height="12" fill="#2E6E6A"/><text x="106" y="310" font-size="11" fill="#8A7F6E">Landline</text><rect x="194" y="300" width="12" height="12" fill="#B78A2E"/><text x="210" y="310" font-size="11" fill="#8A7F6E">Mobile call</text><rect x="322" y="300" width="12" height="12" fill="#6E4A8E"/><text x="338" y="310" font-size="11" fill="#8A7F6E">Messaging apps</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>Some people say that the best way to improve public health is by increasing the number of sports facilities. Others disagree. Discuss both views and give your own opinion.</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-writing-10','Gri Writing 10',true,'IELTS Academic Writing — Task 1 + Task 2') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'writing',60) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,1,'<p>You should spend about 20 minutes on this task.</p><p>The diagram below shows how instant coffee is produced.</p><svg viewBox="0 0 560 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><text x="280" y="20" text-anchor="middle" font-size="12" fill="#8A7F6E" font-weight="bold">How instant coffee is produced</text><rect x="30" y="44" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#2E6E6A" stroke-width="2"/><text x="105" y="73" text-anchor="middle" font-size="11" fill="#8A7F6E">Ripe coffee cherries</text><text x="105" y="87" text-anchor="middle" font-size="11" fill="#8A7F6E">harvested from farms</text><circle cx="44" cy="58" r="10" fill="#2E6E6A"/><text x="44" y="62" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">1</text><line x1="182" y1="76" x2="202" y2="76" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="202,72 208,76 202,80" fill="#8A7F6E"/><rect x="204" y="44" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#B78A2E" stroke-width="2"/><text x="279" y="73" text-anchor="middle" font-size="11" fill="#8A7F6E">Beans removed, dried</text><text x="279" y="87" text-anchor="middle" font-size="11" fill="#8A7F6E">and roasted</text><circle cx="218" cy="58" r="10" fill="#B78A2E"/><text x="218" y="62" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">2</text><line x1="356" y1="76" x2="376" y2="76" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="376,72 382,76 376,80" fill="#8A7F6E"/><rect x="378" y="44" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#6E4A8E" stroke-width="2"/><text x="453" y="73" text-anchor="middle" font-size="11" fill="#8A7F6E">Roasted beans ground</text><text x="453" y="87" text-anchor="middle" font-size="11" fill="#8A7F6E">into powder</text><circle cx="392" cy="58" r="10" fill="#6E4A8E"/><text x="392" y="62" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">3</text><line x1="453" y1="110" x2="453" y2="156" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="449,156 453,162 457,156" fill="#8A7F6E"/><rect x="378" y="162" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#2E6E6A" stroke-width="2"/><text x="453" y="191" text-anchor="middle" font-size="11" fill="#8A7F6E">Ground coffee brewed</text><text x="453" y="205" text-anchor="middle" font-size="11" fill="#8A7F6E">with hot water</text><circle cx="392" cy="176" r="10" fill="#2E6E6A"/><text x="392" y="180" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">4</text><line x1="376" y1="194" x2="358" y2="194" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="358,190 352,194 358,198" fill="#8A7F6E"/><rect x="204" y="162" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#B78A2E" stroke-width="2"/><text x="279" y="191" text-anchor="middle" font-size="11" fill="#8A7F6E">Water removed by</text><text x="279" y="205" text-anchor="middle" font-size="11" fill="#8A7F6E">freeze-drying</text><circle cx="218" cy="176" r="10" fill="#B78A2E"/><text x="218" y="180" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">5</text><line x1="202" y1="194" x2="184" y2="194" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="184,190 178,194 184,198" fill="#8A7F6E"/><rect x="30" y="162" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#6E4A8E" stroke-width="2"/><text x="105" y="191" text-anchor="middle" font-size="11" fill="#8A7F6E">Coffee granules</text><text x="105" y="205" text-anchor="middle" font-size="11" fill="#8A7F6E">packed into jars</text><circle cx="44" cy="176" r="10" fill="#6E4A8E"/><text x="44" y="180" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">6</text><line x1="105" y1="228" x2="105" y2="274" stroke="#8A7F6E" stroke-width="1.5"/><polygon points="101,274 105,280 109,274" fill="#8A7F6E"/><rect x="30" y="280" width="150" height="64" rx="10" fill="#FBF6EC" stroke="#2E6E6A" stroke-width="2"/><text x="105" y="309" text-anchor="middle" font-size="11" fill="#8A7F6E">Sealed jars</text><text x="105" y="323" text-anchor="middle" font-size="11" fill="#8A7F6E">distributed to shops</text><circle cx="44" cy="294" r="10" fill="#2E6E6A"/><text x="44" y="298" text-anchor="middle" font-size="11" fill="#fff" font-weight="bold">7</text></svg><p>Summarise the information by selecting and reporting the main features, and make comparisons where relevant.</p><p><strong>Write at least 150 words.</strong></p>',150,20);
    INSERT INTO ielts_parts (section_id,part_number,task_prompt,word_min,task_time_minutes) VALUES (v_sec,2,'<p>You should spend about 40 minutes on this task. Write about the following topic:</p><p>In some countries young people are encouraged to work or travel for a year between finishing school and starting university. Do the benefits of this outweigh the drawbacks?</p><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p><strong>Write at least 250 words.</strong></p>',250,40);
